def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(float(opp.get('water_requirement', WATER_REQ)))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if not alive_opponents:
        return max(0.0, min(float(budget), DAILY_SALARY * 0.35))

    total_players = 1 + len(alive_opponents)
    total_req = WATER_REQ
    for req in opp_requirements:
        total_req += req

    scarcity = total_req / max(supply, 1.0)
    high_supply = supply >= 22.0
    low_supply = supply <= 17.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if low_supply:
        danger += 1
    if scarcity > 2.4:
        danger += 1

    if danger >= 4:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif danger >= 2:
        bid = max(DAILY_SALARY * 0.72, avg_prev + 2.0, highest_prev * 0.88)
    else:
        if high_supply and highest_prev >= 95.0:
            bid = DAILY_SALARY * 0.28
        elif high_supply:
            bid = DAILY_SALARY * 0.4
        elif low_supply:
            bid = max(DAILY_SALARY * 0.62, highest_prev * 0.72)
        else:
            bid = max(DAILY_SALARY * 0.5, avg_prev * 0.7)

    rich_opp_count = 0
    pressured_opp_count = 0
    for opp in alive_opponents:
        if float(opp.get('budget', 0.0)) > budget + 150:
            rich_opp_count += 1
        if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
            pressured_opp_count += 1

    if rich_opp_count >= 2 and danger <= 1:
        bid *= 0.85
    if pressured_opp_count >= 2 and danger <= 2 and not low_supply:
        bid *= 0.9

    if day >= 8:
        bid *= 1.08
    if budget < DAILY_SALARY * 2:
        bid = min(bid, DAILY_SALARY * 0.78)
    if budget < DAILY_SALARY:
        bid = min(bid, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.98)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        # If no one else is alive, conserve budget but stay safe
        return min(my_status['budget'], DAILY_SALARY * 0.45)

    # Read yesterday bids from previous_trace (immediate reaction only)
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Determine pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_highest_prev_bid = sorted_bids[1]

    # Compute a conservative target based on supply: if supply is tight, increase bid.
    # supply is between 15 and 25; translate to scarcity level.
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)  # 0 (plenty) to 1 (tight)
    scarcity = max(0.0, min(1.0, scarcity))

    # Base bid: aim around mid of typical survivor bids (~90-110) but not max.
    # If highest_prev_bid is very high, we need to contest more.
    base = DAILY_SALARY * (0.48 + 0.25 * scarcity)  # ~43.2 to ~66.6

    # If others were bidding near/above daily salary, we must raise.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If our hp is low, pay more; otherwise just slightly over second-highest.
        if my_status['hp'] <= 2:
            target = max(base, min(my_status['budget'], DAILY_SALARY * 0.95))
        else:
            # Try to beat the likely winner without going to their max.
            target = max(base, second_highest_prev_bid + 2.5)
    else:
        # If yesterday pressure was moderate, bid to secure water but conserve budget.
        # Slightly above base, and if highest_prev_bid exists, add a small increment.
        if highest_prev_bid > 0:
            target = max(base, min(highest_prev_bid + 1.5, DAILY_SALARY * (0.75 + 0.1 * scarcity)))
        else:
            target = base

    # If we are already on no-water streak, escalate
    no_water_days = my_status.get('no_water_days', 0)
    if no_water_days >= 2:
        target = max(target, DAILY_SALARY * (0.75 + 0.15 * scarcity))
    if no_water_days >= 3:
        target = max(target, DAILY_SALARY * 0.95)

    # Ensure we don't exceed budget
    budget = float(my_status['budget'])
    if budget <= 0:
        return 0.0

    # Final clamp: never bid above a reasonable ceiling to avoid elimination by spending
    ceiling = DAILY_SALARY * (1.05 + 0.05 * scarcity)
    target = min(float(target), ceiling, budget)

    # If target is too low to be meaningful vs typical bids, nudge upward.
    # This helps against aggressive survivors.
    if target < DAILY_SALARY * 0.55 and my_status['hp'] > 2:
        target = min(budget, DAILY_SALARY * (0.6 + 0.1 * scarcity))

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    # If current supply is less than my requirement, I cannot get water. Bid minimum to save budget.
    if day_context['supply'] < WATER_REQ:
        return min(my_status['budget'], 1)

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If no opponents are alive, bid very low to save budget.
    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Calculate days remaining to gauge urgency
    days_remaining = EPISODE_DAYS - day_context['day'] + 1

    bid_amount = 0

    # Prioritize survival if HP is critical, we've missed water recently, or nearing the end of the episode
    if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1 or days_remaining <= 2:
        # If opponents were bidding high, try to outbid them more aggressively
        if highest_prev_bid > DAILY_SALARY * 0.7:
            bid_amount = highest_prev_bid + (DAILY_SALARY * 0.1) # Add 10% of salary to outbid
        else:
            bid_amount = DAILY_SALARY * 0.95 # Very high bid to secure water
    else:
        # Normal bidding strategy
        if highest_prev_bid > DAILY_SALARY * 0.6: # Opponents are bidding relatively high
            bid_amount = max(DAILY_SALARY * 0.65, highest_prev_bid + (DAILY_SALARY * 0.05)) # Slightly outbid
        elif highest_prev_bid > 0: # Opponents made a bid
            bid_amount = max(DAILY_SALARY * 0.55, highest_prev_bid + (DAILY_SALARY * 0.03)) # Small increase
        else: # No significant previous bids (e.g., first day, or opponents bid very low)
            bid_amount = DAILY_SALARY * 0.5 # Moderate default bid

    # Ensure bid doesn't exceed budget and is at least 1
    final_bid = min(my_status['budget'], max(1, bid_amount))

    return final_bid

